<div class="page-actions"><div><p class="muted">Kelola data master <?=e(strtolower($config['singular']))?> Gudang Kita.</p></div><a class="btn btn-primary" href="?page=masters&type=<?=e($type)?>&action=create">+ Tambah <?=e($config['singular'])?></a></div>
<div class="card filter-card"><form class="filter-grid" method="get"><input type="hidden" name="page" value="masters"><input type="hidden" name="type" value="<?=e($type)?>"><input name="search" value="<?=e($filters['search'])?>" placeholder="Cari kode / nama..."><select name="status"><option value="">Semua status</option><option value="Active" <?=$filters['status']==='Active'?'selected':''?>>Active</option><option value="Inactive" <?=$filters['status']==='Inactive'?'selected':''?>>Inactive</option></select><?php if($type==='products'):?><select name="category_id"><option value="">Semua kategori</option><?php foreach($categories as $category):?><option value="<?=$category['id']?>" <?=$filters['category_id']==$category['id']?'selected':''?>><?=e($category['name'])?></option><?php endforeach;?></select><select name="stock_status"><option value="">Semua status stok</option><option value="low" <?=$filters['stock_status']==='low'?'selected':''?>>Stok rendah</option><option value="normal" <?=$filters['stock_status']==='normal'?'selected':''?>>Stok normal</option></select><?php endif;?><?php include BASE_PATH.'/views/masters/sort-field.php'; ?><button class="btn btn-primary">Cari</button><a class="btn" href="?page=masters&type=<?=e($type)?>">Reset</a></form></div>
<div class="card"><div class="table-wrap"><table><thead><tr><?php foreach($config['fields'] as $f):?><th><?=e(ucwords(str_replace('_',' ',$f)))?></th><?php endforeach;?><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($config['fields'] as $f):?><td><?php if($f==='status'):?><span class="badge status-<?=strtolower($r[$f])?>"><?=e($r[$f])?></span><?php elseif($f==='category_id'):?><?=e($r['category_name']??'-')?><?php elseif(in_array($f,['purchase_price','selling_price'],true)):?>Rp <?=number_format((float)$r[$f],0,',','.')?><?php else:?><?=e($r[$f])?><?php endif;?></td><?php endforeach;?><td><div class="actions"><a class="btn btn-sm" href="?page=masters&type=<?=e($type)?>&action=edit&id=<?=$r['id']?>">Edit</a><?php if(in_array($type,['products','categories','suppliers','customers','warehouses'],true)&&$r['status']==='Active'):?><form method="post" action="?page=masters&amp;type=<?=e($type)?>&amp;action=deactivate&amp;id=<?=$r['id']?>" onsubmit="return confirm('Nonaktifkan data ini?')"><?=$csrfField?><input type="hidden" name="type" value="<?=e($type)?>"><button class="btn btn-sm">Nonaktifkan</button></form><?php else:?><form method="post" action="?page=masters&amp;type=<?=e($type)?>&amp;action=delete&amp;id=<?=$r['id']?>" onsubmit="return confirm('Hapus data ini?')"><?=$csrfField?><input type="hidden" name="type" value="<?=e($type)?>"><button class="btn btn-sm danger-btn">Hapus</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="20" class="empty">Belum ada data.</td></tr><?php endif;?></tbody></table></div><?php if($pagination&&$pagination['pages']>1):?><nav class="pagination" aria-label="Pagination master"><?php $query=['page'=>'masters','type'=>$type,'search'=>$filters['search'],'status'=>$filters['status'],'category_id'=>$filters['category_id'],'stock_status'=>$filters['stock_status'],'sort'=>$filters['sort']];if($pagination['page']>1):$query['current_page']=$pagination['page']-1;?><a class="page-btn" href="?<?=e(http_build_query($query))?>">‹ Sebelumnya</a><?php endif;?><?php for($i=1;$i<=$pagination['pages'];$i++):$query['current_page']=$i;?><a class="page-btn <?=$i===$pagination['page']?'current':''?>" href="?<?=e(http_build_query($query))?>"><?=$i?></a><?php endfor;?><?php if($pagination['page']<$pagination['pages']):$query['current_page']=$pagination['page']+1;?><a class="page-btn" href="?<?=e(http_build_query($query))?>">Berikutnya ›</a><?php endif;?></nav><?php endif;?></div>
